#[inductive(consume_start)]
fn consume_start_inductive(pre: Self, post: Self) {
    // After consume_start:
    // - consumer state changed from Idle(head) to Consuming(head)
    // - storage[head] was removed

    // Prove that valid_storage_all still holds
    assert(forall|i: nat| 0 <= i && i < post.len() ==> post.valid_storage_at_idx(i)) by {
        assert forall|i: nat| 0 <= i && i < post.len() implies post.valid_storage_at_idx(i) by {
            let head = pre.consumer.get_Idle_0(); // head from pre-state

            if i == head {
                // For the head index, it's now checked out (in consuming state)
                assert(post.is_checked_out(i));
                assert(!post.storage.dom().contains(i));
                assert(post.valid_storage_at_idx(i));
            } else {
                // For all other indices, storage content is unchanged except at head
                assert(post.storage.dom().contains(i) == pre.storage.dom().contains(i));

                if post.storage.dom().contains(i) {
                    assert(post.storage.index(i) === pre.storage.index(i));
                    assert(post.storage.index(i).id() == post.backing_cells.index(i as int));

                    // Need to show that in_active_range is preserved
                    if post.in_active_range(i) {
                        assert(pre.in_active_range(i));
                        assert(pre.storage.index(i).is_init());
                        assert(post.storage.index(i).is_init());
                    } else {
                        assert(!pre.in_active_range(i));
                        assert(pre.storage.index(i).is_uninit());
                        assert(post.storage.index(i).is_uninit());
                    }
                }

                assert(post.valid_storage_at_idx(i));
            }
        }
