    assert(forall|i: nat| #![trigger post.valid_storage_at_idx(i)] 0 <= i && i < post.len() ==> post.valid_storage_at_idx(i)) by {
        assert forall|i: nat| 0 <= i && i < post.len() implies post.valid_storage_at_idx(i) by {
            // In the post state, the consumer is now Consuming(head)
            let head = pre.consumer.get_Idle_0();

            if i == head {
                // The permission at index 'head' has been withdrawn/check out
                assert(post.is_checked_out(i));
                // So there should be no storage permission at this index
                assert(!post.storage.dom().contains(i));
                // And valid_storage_at_idx should hold for this case
                assert(post.valid_storage_at_idx(i));
            } else {
                // For all other indices, the storage is unchanged
                assert(post.storage.dom().contains(i) == pre.storage.dom().contains(i));

                if post.storage.dom().contains(i) {
                    // The permission object is the same
                    assert(post.storage.index(i) === pre.storage.index(i));
                    // Still refers to the same cell ID
                    assert(post.storage.index(i).id() == post.backing_cells.index(i as int));

                    // The active range status should be the same since head/tail unchanged
                    assert(post.in_active_range(i) == pre.in_active_range(i));

