                        // Was full in pre, should still be full in post
                        assert(pre.storage.index(i).is_init());
                        assert(post.storage.index(i).is_init());
                    } else {
                        // Was empty in pre, should still be empty in post
                        assert(pre.storage.index(i).is_uninit());
                        assert(post.storage.index(i).is_uninit());
                    }
                }

                // Therefore, valid_storage_at_idx holds
                assert(post.valid_storage_at_idx(i));
            }
        }
    }
