fn consume_start_inductive(pre: Self, post: Self) {
    // Pre-condition: pre satisfies all invariants
    assert(pre.valid_storage_all());
    assert(pre.in_bounds());

    let head = pre.consumer.get_Idle_0();

    // In the consume_start transition:
    // - post.consumer becomes ConsumerState::Consuming(head)
    // - post.storage becomes pre.storage \ {head}
    // - All other fields remain identical

    // Establish the main invariant for post state
    assert forall|i: nat| 0 <= i && i < post.len() implies post.valid_storage_at_idx(i) by {
        if i == head {
            // After consume_start, index 'head' is checked out (no storage permission)
            assert(post.is_checked_out(i));
            assert(!post.storage.dom().contains(i));
            assert(post.valid_storage_at_idx(i));
        } else {
            // For all other indices, permission content is unchanged
            assert(post.storage.dom().contains(i) == pre.storage.dom().contains(i));

            if post.storage.dom().contains(i) {
                // Same permission object in both states
                assert(post.storage.index(i) === pre.storage.index(i));
                assert(pre.valid_storage_at_idx(i)); // From pre's invariant

                // Transfer key facts from pre to post
                assert(post.storage.index(i).id() == post.backing_cells.index(i as int));
                assert(post.in_active_range(i) == pre.in_active_range(i));

                if post.in_active_range(i) {
                    assert(pre.storage.index(i).is_init());
                    assert(post.storage.index(i).is_init());
                } else {
                    assert(pre.storage.index(i).is_uninit());  
                    assert(post.storage.index(i).is_uninit());
                }
            }

            assert(post.valid_storage_at_idx(i));
        }
    };

    assert(post.valid_storage_all());
}

