#[inductive(consume_start)]
fn consume_start_inductive(pre: Self, post: Self) {
    // Pre-condition: pre satisfies all invariants, including valid_storage_all
    assert(pre.valid_storage_all());

    let head = pre.consumer.get_Idle_0();

    // Post-state properties from the transition:
    // - post.consumer == ConsumerState::Consuming(head)  
    // - post.storage == pre.storage.remove(head)
    // - All other fields are unchanged

    // Prove post.valid_storage_all by showing post.valid_storage_at_idx(i) for all i
    assert forall|i: nat| 0 <= i && i < post.len() implies post.valid_storage_at_idx(i) by {
        if i == head {
            // At index 'head', permission is now checked out (not in storage)
            assert(post.is_checked_out(i));
            assert(!post.storage.dom().contains(i));
            // By definition of valid_storage_at_idx, when checked out, validity means !storage.dom().contains(i)
            assert(post.valid_storage_at_idx(i));
        } else {
            // For all other indices, storage content is identical
            assert(post.storage.dom().contains(i) == pre.storage.dom().contains(i));

            if post.storage.dom().contains(i) {
                // Storage contains the same permission object at this index
                assert(post.storage.index(i) === pre.storage.index(i));

                // Since pre.valid_storage_at_idx(i) and the objects are identical:
                assert(pre.valid_storage_at_idx(i));

                // The cell ID property transfers directly:  
                assert(post.storage.index(i).id() == post.backing_cells.index(i as int));

                // The active range status is unchanged (since head/tail unchanged in transition):
                assert(post.in_active_range(i) == pre.in_active_range(i));

                // Hence the initialization status is unchanged:
                assert(post.storage.index(i).is_init() == pre.storage.index(i).is_init());
                assert(post.storage.index(i).is_uninit() == pre.storage.index(i).is_uninit());
            }

            // Since all components of valid_storage_at_idx are satisfied, it holds
            assert(post.valid_storage_at_idx(i));
        }
    }

    // Conclude that post.valid_storage_all holds
    assert(post.valid_storage_all());
}

